package main

import (
	"database/sql"
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"
)

type Product struct {
	ID         string `json:"id"`
	Name       string `json:"name"`
	PriceCents int64  `json:"priceCents"`
}

func listActiveProducts(db *sql.DB, categoryID string, limit int) ([]Product, error) {
	rows, err := db.Query(
		"SELECT id, name, price_cents FROM products WHERE category_id = $1 AND active ORDER BY name LIMIT $2",
		categoryID,
		limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	products := make([]Product, 0, limit)
	for rows.Next() {
		var product Product
		if err := rows.Scan(&product.ID, &product.Name, &product.PriceCents); err != nil {
			return nil, err
		}
		products = append(products, product)
	}
	return products, rows.Err()
}

func registerProductRoutes(router *gin.Engine, db *sql.DB) {
	router.GET("/api/products", func(c *gin.Context) {
		categoryID := c.Query("category")
		if categoryID == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "category is required"})
			return
		}
		limit, err := strconv.Atoi(c.DefaultQuery("limit", "50"))
		if err != nil || limit < 1 || limit > 50 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "limit must be between 1 and 50"})
			return
		}
		products, err := listActiveProducts(db, categoryID, limit)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "could not load products"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"products": products})
	})
}
